create extension if not exists pgcrypto;
create type horse_status as enum ('urgent','intake','quarantine','evaluation','rehabilitation','adoptable','foster','sanctuary','placed','deceased');
create type case_priority as enum ('critical','high','normal','low');
create type care_kind as enum ('veterinary','dental','nutrition','medication','farrier','behavior','transport','quarantine','other');
create table if not exists horses(id uuid primary key default gen_random_uuid(),case_number text unique not null,name text,status horse_status not null default 'intake',priority case_priority not null default 'normal',breed text,sex text,age_text text,color text,markings text,source text,current_location text,origin_location text,intake_date timestamptz,arrival_date timestamptz,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists care_events(id uuid primary key default gen_random_uuid(),horse_id uuid not null references horses(id) on delete cascade,kind care_kind not null,occurred_at timestamptz not null default now(),provider text,findings text,treatment text,next_step text,cost_cents integer default 0,document_url text,created_at timestamptz not null default now());
create table if not exists tasks(id uuid primary key default gen_random_uuid(),horse_id uuid references horses(id) on delete cascade,title text not null,description text,priority case_priority not null default 'normal',due_at timestamptz,assigned_to uuid,completed_at timestamptz,created_at timestamptz not null default now());
create table if not exists help_requests(id uuid primary key default gen_random_uuid(),name text not null,email text not null,phone text,category text not null,message text,status text not null default 'new',created_at timestamptz not null default now());
create table if not exists sponsorships(id uuid primary key default gen_random_uuid(),horse_id uuid references horses(id) on delete set null,donor_name text,donor_email text,amount_cents integer not null,recurring boolean not null default false,started_at timestamptz not null default now(),status text not null default 'active');
create table if not exists transport_cases(id uuid primary key default gen_random_uuid(),horse_id uuid references horses(id) on delete cascade,origin text not null,destination text not null,requested_departure timestamptz,carrier_name text,carrier_phone text,status text not null default 'needs_transport',notes text,created_at timestamptz not null default now());
create table if not exists inventory(id uuid primary key default gen_random_uuid(),item text not null,category text not null,quantity numeric not null default 0,unit text,reorder_level numeric default 0,supplier text,notes text,updated_at timestamptz not null default now());
create table if not exists media(id uuid primary key default gen_random_uuid(),horse_id uuid references horses(id) on delete cascade,storage_path text not null,caption text,created_at timestamptz not null default now());
create index if not exists care_events_horse_idx on care_events(horse_id,occurred_at desc);
create index if not exists tasks_status_idx on tasks(completed_at,due_at);
create index if not exists horses_status_idx on horses(status,priority);
create index if not exists help_requests_status_idx on help_requests(status,created_at desc);
alter table horses enable row level security; alter table care_events enable row level security; alter table tasks enable row level security; alter table help_requests enable row level security; alter table sponsorships enable row level security; alter table transport_cases enable row level security; alter table inventory enable row level security; alter table media enable row level security;
create policy "public can submit help" on help_requests for insert to anon with check (true);
create policy "public cannot read help" on help_requests for select to anon using (false);
